function Nx.ModQuests:Load8()
    local ModQuests = Nx.ModQuests:Data8()
    local count = 0
    for key, val in pairs(ModQuests) do
        Nx.Quests[key] = val
        count = count + 1
    end
    ModQuests = {}
    return count
end

function Nx.ModQuests:Clear8()
    --ModQuests = {}
end
